index 0000000..53bb9b5
--- /dev/null
+++ b/projects/realtime-agent/tests/vscode-extension/log.test.ts
@@ -0,0 +1,61 @@
+import assert from "node:assert/strict";
+import { mkdirSync, mkdtempSync, readFileSync, rmSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { test } from "node:test";
+
+import { CreateExtensionLog } from "../../src/vscode-extension/src/log.js";
+
+function CreateFakeOutputChannel(): { channel: import("vscode").OutputChannel; lines: string[] }
+{
+  const lines: string[] = [];
+  const channel = {
+    appendLine(message: string)
+    {
+      lines.push(message);
+    },
+  } as import("vscode").OutputChannel;
+
+  return { channel, lines };
+}
+
+test("CreateExtensionLog writes structured JSONL when repo root is present", () =>
+{
+  const repoRoot = mkdtempSync(join(tmpdir(), "sheaf-log-repo-"));
+  const logDir = join(repoRoot, "logs", "realtime-agent");
+  mkdirSync(logDir, { recursive: true });
+  const logPath = join(logDir, "vscode-extension.jsonl");
+
+  try
+  {
+    const { channel, lines } = CreateFakeOutputChannel();
+    const log = CreateExtensionLog({
+      channel,
+      runtimeLogPath: logPath,
+    });
+
+    log.LogEvent("extension_session_started", { session_id: "abc" });
+
+    const content = readFileSync(logPath, "utf8").trim();
+    const entry = JSON.parse(content) as { event: string; fields?: Record<string, unknown> };
+    assert.equal(entry.event, "extension_session_started");
+    assert.equal(entry.fields?.session_id, "abc");
+    assert.ok(lines.some((line) => line.includes("extension_session_started")));
+  }
+  finally
+  {
+    rmSync(repoRoot, { recursive: true, force: true });
+  }
+});
+
+test("CreateExtensionLog keeps Output Channel logging without repo root", () =>
+{
+  const { channel, lines } = CreateFakeOutputChannel();
+  const log = CreateExtensionLog({ channel });
+
+  log.Line("hello");
+  log.Error("boom", new Error("detail"));
+
+  assert.equal(lines[0], "hello");
+  assert.ok(lines[1]?.startsWith("boom: Error: detail"));
+});
diff --git a/projects/realtime-agent/tests/vscode-extension/repoConfig.test.ts b/projects/realtime-agent/tests/vscode-extension/repoConfig.test.ts
new file mode 100644
index 0000000..55d2c81
--- /dev/null
+++ b/projects/realtime-agent/tests/vscode-extension/repoConfig.test.ts
@@ -0,0 +1,103 @@
+import assert from "node:assert/strict";
+import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { test } from "node:test";
+
+import {
+  FindSheafRepositoryRoot,
+  FindSheafRepositoryRootFromWorkspaceFolders,
+  LoadOpenAiApiKeyFromRepoConfig,
+  ResolveExtensionRuntimeLogPath,
+} from "../../src/vscode-extension/src/repoConfig.js";
+
+function CreateFakeSheafRepoRoot(): string
+{
+  const root = mkdtempSync(join(tmpdir(), "sheaf-repo-"));
+  mkdirSync(join(root, "config"), { recursive: true });
+  mkdirSync(join(root, "structure"), { recursive: true });
+  mkdirSync(join(root, "projects", "realtime-agent"), { recursive: true });
+  writeFileSync(join(root, "config", "services.json"), "{}");
+  return root;
+}
+
+test("FindSheafRepositoryRoot locates repository root from nested workspace folder", () =>
+{
+  const root = CreateFakeSheafRepoRoot();
+  const nested = join(root, "projects", "realtime-agent", "src", "vscode-extension");
+
+  try
+  {
+    mkdirSync(nested, { recursive: true });
+    assert.equal(FindSheafRepositoryRoot(nested), root);
+  }
+  finally
+  {
+    rmSync(root, { recursive: true, force: true });
+  }
+});
+
+test("FindSheafRepositoryRootFromWorkspaceFolders returns first matching repo root", () =>
+{
+  const root = CreateFakeSheafRepoRoot();
+
+  try
+  {
+    const found = FindSheafRepositoryRootFromWorkspaceFolders([
+      { uri: { fsPath: join(root, "projects", "realtime-agent") } },
+    ]);
+    assert.equal(found, root);
+  }
+  finally
+  {
+    rmSync(root, { recursive: true, force: true });
+  }
+});
+
+test("LoadOpenAiApiKeyFromRepoConfig reads openai_api_key from config/api_keys.json", async () =>
+{
+  const root = CreateFakeSheafRepoRoot();
+
+  try
+  {
+    writeFileSync(
+      join(root, "config", "api_keys.json"),
+      JSON.stringify({ openai_api_key: "sk-repo-key" }),
+    );
+
+    const loaded = await LoadOpenAiApiKeyFromRepoConfig(root);
+    assert.equal(loaded.apiKey, "sk-repo-key");
+    assert.equal(loaded.error, undefined);
+  }
+  finally
+  {
+    rmSync(root, { recursive: true, force: true });
+  }
+});
+
+test("LoadOpenAiApiKeyFromRepoConfig reports parse failures", async () =>
+{
+  const root = CreateFakeSheafRepoRoot();
+
+  try
+  {
+    writeFileSync(join(root, "config", "api_keys.json"), "{not-json");
+
+    const loaded = await LoadOpenAiApiKeyFromRepoConfig(root);
+    assert.equal(loaded.apiKey, undefined);
+    assert.ok(loaded.error?.includes("api_keys.json"));
+  }
+  finally
+  {
+    rmSync(root, { recursive: true, force: true });
+  }
+});
+
+test("ResolveExtensionRuntimeLogPath uses logs/realtime-agent under repo root", () =>
+{
+  const root = "/tmp/sheaf";
+  assert.equal(
+    ResolveExtensionRuntimeLogPath(root),
+    join(root, "logs", "realtime-agent", "vscode-extension.jsonl"),
+  );
+});
