+
+    const loaded = await LoadOpenAiApiKeyFromRepoConfig(root);
+    assert.equal(loaded.apiKey, undefined);
+    assert.ok(loaded.error?.includes("api_keys.json"));
+  }
+  finally
+  {
+    rmSync(root, { recursive: true, force: true });
+  }
+});
+
