import { appendFileSync, mkdirSync } from "node:fs";
import path from "node:path";

import {
  GetDefaultRealtimeAgentPaths,
} from "./repo_paths.js";

export interface RuntimeLogEntry
{
  timestamp: string;
  level: "info" | "warn" | "error";
  event: string;
  message?: string;
  fields?: Record<string, unknown>;
}

export interface RuntimeLoggerOptions
{
  logPath?: string;
  repoRoot?: string;
}

export interface RuntimeLogger
{
  Log(event: string, fields?: Record<string, unknown>): void;
  LogWarn(event: string, fields?: Record<string, unknown>): void;
  LogError(event: string, fields?: Record<string, unknown>): void;
  Close(): void;
}

const x_sensitiveFieldPattern = /api[_-]?key|authorization|secret|token|password/i;

function SanitizeFields(
  fields?: Record<string, unknown>,
): Record<string, unknown> | undefined
{
  if (fields === undefined)
  {
    return undefined;
  }

  const sanitized: Record<string, unknown> = {};

  for (const [key, value] of Object.entries(fields))
  {
    if (x_sensitiveFieldPattern.test(key))
    {
      sanitized[key] = "[redacted]";
      continue;
    }

    if (key === "pcmBase64" || key === "audio" || key === "frame")
    {
      sanitized[key] = "[redacted]";
      continue;
    }

    sanitized[key] = value;
  }

  return sanitized;
}

function BuildEntry(
  level: RuntimeLogEntry["level"],
  event: string,
  fields?: Record<string, unknown>,
): RuntimeLogEntry
{
  return {
    timestamp: new Date().toISOString(),
    level,
    event,
    fields: SanitizeFields(fields),
  };
}

export function CreateRuntimeLogger(options: RuntimeLoggerOptions = {}): RuntimeLogger
{
  const logPath =
    options.logPath ?? GetDefaultRealtimeAgentPaths(options.repoRoot).runtimeLogPath;

  mkdirSync(path.dirname(logPath), { recursive: true });

  const write = (entry: RuntimeLogEntry): void =>
  {
    appendFileSync(logPath, `${JSON.stringify(entry)}\n`, "utf8");
  };

  return {
    Log(event, fields)
    {
      write(BuildEntry("info", event, fields));
    },
    LogWarn(event, fields)
    {
      write(BuildEntry("warn", event, fields));
    },
    LogError(event, fields)
    {
      write(BuildEntry("error", event, fields));
    },
    Close()
    {
    },
  };
}

{
  "name": "sheaf-vscode-extension",
  "displayName": "Sheaf",
  "description": "Voice-driven realtime agent for VS Code (Sheaf)",
  "version": "0.0.1",
  "publisher": "sheaf",
  "private": true,
  "engines": {
    "vscode": "^1.85.0"
  },
  "categories": [
    "Other"
  ],
  "activationEvents": [
    "onCommand:sheaf.realtime.toggleSession",
    "onCommand:sheaf.realtime.commitAndRespond",
    "onView:sheaf.chatView"
  ],
  "main": "./out/extension.js",
  "contributes": {
    "viewsContainers": {
      "activitybar": [
        {
          "id": "sheafContainer",
          "title": "Sheaf",
          "icon": "media/sheaf.svg"
        }
      ]
    },
    "views": {
      "sheafContainer": [
        {
          "id": "sheaf.chatView",
          "name": "Realtime Chat",
          "type": "webview"
        }
      ]
    },
    "commands": [
      {
        "command": "sheaf.realtime.toggleSession",
        "title": "Sheaf: Toggle Realtime Session"
      },
      {
        "command": "sheaf.realtime.commitAndRespond",
        "title": "Sheaf: Commit Audio And Request Response"
      }
    ],
    "keybindings": [
      {
        "command": "sheaf.realtime.toggleSession",
        "key": "f16"
      },
      {
        "command": "sheaf.realtime.commitAndRespond",
        "key": "f20"
      }
    ],
    "configuration": {
      "title": "Sheaf Realtime",
      "properties": {
        "sheaf.realtime.openAiApiKey": {
          "type": "string",
          "default": "",
          "description": "OpenAI API key (optional if stored in VS Code Secret Storage or config/api_keys.json)."
        },
        "sheaf.realtime.model": {
          "type": "string",
          "default": "gpt-realtime-2"
        },
        "sheaf.realtime.systemPrompt": {
          "type": "string",
          "default": "",
          "description": "Overrides the built-in sheaf VS Code system prompt when non-empty."
        },
        "sheaf.realtime.inputDevice": {
          "type": "string",
          "default": "",
          "description": "Optional microphone device id or substring (see realtime-agent list-input-devices)."
        },
        "sheaf.realtime.safetyIdentifier": {
          "type": "string",
          "default": "",
          "description": "Optional safety identifier header for OpenAI Realtime."
        }
      }
    }
  },
  "scripts": {
    "build": "node esbuild.config.mjs",
    "dev": "node esbuild.config.mjs --watch",
    "lint": "tsc -p tsconfig.json --noEmit",
    "test": "rm -rf .test-dist && tsc -p tsconfig.test.json && node scripts/run-vscode-extension-tests.mjs",
    "clean": "rm -rf out .test-dist node_modules *.vsix"
  },
  "dependencies": {
    "better-sqlite3": "^12.10.0",
    "naudiodon": "^2.3.6",
    "realtime-agent-lib": "*"
  },
  "devDependencies": {
    "@types/node": "^22.10.1",
    "@types/vscode": "^1.85.0",
    "esbuild": "^0.24.0",
    "typescript": "^5.7.2"
  }
}

